package com.vit.archds.config;
import com.vit.archds.security.JwtAuthFilter; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.*;
@Configuration public class SecurityConfig { @Value("${app.cors.allowed-origins}") String origins; private final JwtAuthFilter jwt; public SecurityConfig(JwtAuthFilter j){jwt=j;} @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();} @Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(cors())).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health","/api/health").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/projects/**").hasAnyRole("ADMIN","ARCHITECT").requestMatchers(org.springframework.http.HttpMethod.POST,"/api/projects/*/run-analysis").hasAnyRole("ADMIN","ARCHITECT","USER").requestMatchers(org.springframework.http.HttpMethod.POST,"/api/projects/*/decision").hasAnyRole("ADMIN","ARCHITECT","REVIEWER").requestMatchers("/api/audit").hasAnyRole("ADMIN","ARCHITECT","REVIEWER").anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();} @Bean CorsConfigurationSource cors(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.asList(origins.split(",")));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}}
